--
-- Table structure for table `kepanitiaan_sesi_absensis`
--

DROP TABLE IF EXISTS `kepanitiaan_sesi_absensis`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kepanitiaan_sesi_absensis` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kepanitiaan_id` bigint unsigned NOT NULL,
  `nama_sesi` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tanggal` date DEFAULT NULL,
  `waktu_mulai_datang` time DEFAULT NULL,
  `waktu_selesai_datang` time DEFAULT NULL,
  `waktu_mulai_pulang` time DEFAULT NULL,
  `waktu_selesai_pulang` time DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `token` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `legacy_slug` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
