INSERT INTO `laporan_pengembangans` VALUES (1,1,'2026/2027','Laporan Pencapaian Pengembangan Universitas Ibnu Sina Tahun 2026','Pada periode ini, Universitas Ibnu Sina (UIS) telah merealisasikan 92% program kerja strategis yang ditetapkan oleh Rektorat dan Yayasan Pendidikan Ibnu Sina Batam (YAPISTA).\nFokus pencapaian meliputi peningkatan akreditasi seluruh program studi menuju Baik Sekali dan Unggul, akselerasi studi doktor (S3) dosen, penambahan kuota penerimaan mahasiswa baru, hilirisasi hasil riset terapan bersama industri kawasan Batam, serta digitalisasi tata kelola terintegrasi.','{\"catatan\": \"Peningkatan peminat prodi Teknik Informatika dan Manajemen melonjak 18%. Beasiswa KIP-Kuliah dan Yayasan terserap 100%.\", \"target_pmb\": 1250, \"total_aktif\": 4620, \"ipk_rata_rata\": \"3.48\", \"realisasi_pmb\": 1180, \"jumlah_lulusan\": 710, \"tingkat_retensi\": 93.4}','[{\"nama\": \"Teknik Informatika\", \"status\": \"Persiapan Akreditasi Unggul & Kelas Internasional\", \"jenjang\": \"S1\", \"lembaga\": \"LAM INFOKOM\", \"akreditasi\": \"Baik Sekali\", \"kadaluarsa\": \"2028-08-30\"}, {\"nama\": \"Sistem Informasi\", \"status\": \"Peningkatan Kurikulum OBE & Lab IoT\", \"jenjang\": \"S1\", \"lembaga\": \"LAM INFOKOM\", \"akreditasi\": \"Baik Sekali\", \"kadaluarsa\": \"2027-10-15\"}, {\"nama\": \"Teknik Industri\", \"status\": \"Kerjasama Magang Industri Galangan Kapal & Manufaktur Batam\", \"jenjang\": \"S1\", \"lembaga\": \"LAM TEKNIK\", \"akreditasi\": \"Baik Sekali\", \"kadaluarsa\": \"2028-05-20\"}, {\"nama\": \"Kesehatan Masyarakat\", \"status\": \"Pengembangan Peminatan K3 Industri Maritim\", \"jenjang\": \"S1\", \"lembaga\": \"LAM-PTKes\", \"akreditasi\": \"Baik Sekali\", \"kadaluarsa\": \"2028-12-10\"}, {\"nama\": \"Manajemen\", \"status\": \"Pengembangan Inkubator Bisnis & Kewirausahaan Mahasiswa\", \"jenjang\": \"S1\", \"lembaga\": \"LAMEMBA\", \"akreditasi\": \"Baik Sekali\", \"kadaluarsa\": \"2028-03-12\"}, {\"nama\": \"Akuntansi\", \"status\": \"Pemberian Sertifikasi Kompetensi Teknisi Akuntansi\", \"jenjang\": \"S1\", \"lembaga\": \"LAMEMBA\", \"akreditasi\": \"Baik Sekali\", \"kadaluarsa\": \"2027-06-25\"}, {\"nama\": \"Ilmu Hukum\", \"status\": \"Penguatan Pos Bantuan Hukum (Posbakum) Mahasiswa\", \"jenjang\": \"S1\", \"lembaga\": \"BAN-PT\", \"akreditasi\": \"Baik Sekali\", \"kadaluarsa\": \"2028-09-01\"}, {\"nama\": \"Magister Manajemen (S2)\", \"status\": \"Prodi Pascasarjana Baru Berjalan Efektif\", \"jenjang\": \"S2\", \"lembaga\": \"LAMEMBA\", \"akreditasi\": \"Baik\", \"kadaluarsa\": \"2029-01-15\"}]','{\"wilayah\": 25, \"nasional\": 18, \"keterangan\": \"Juara 1 Lomba Inovasi Teknologi Tepat Guna Tingkat Nasional, Medali Emas Kompetisi Robotika Wilayah Sumatera, serta Best Paper pada International Conference on Sustainable Technology.\", \"internasional\": 4}','{\"dosen_s2\": 84, \"dosen_s3\": 26, \"pelatihan\": \"Workshop Penulisan Proposal Hibah Dikti, Bimtek Kurikulum Berbasis OBE, Sertifikasi Pengadaan Barang/Jasa untuk Tendik, dan Pelatihan Asesor Kompetensi BNSP.\", \"dosen_lektor\": 46, \"dosen_serdos\": 58, \"tendik_tetap\": 42, \"dosen_studi_s3\": 14, \"tendik_kontrak\": 16, \"dosen_guru_besar\": 4, \"dosen_asisten_ahli\": 38, \"tendik_sertifikasi\": 22, \"dosen_lektor_kepala\": 18}','{\"buku\": 15, \"dana_pkm\": \"Rp 310.000.000\", \"hki_paten\": 19, \"dana_penelitian\": \"Rp 580.000.000\", \"publikasi_sinta\": 64, \"publikasi_scopus\": 22}','{\"mitra_pt\": 18, \"realisasi\": \"Kerjasama magang bersertifikat dan rekrutmen lulusan dengan kawasan industri Mukakuning & Kabil, riset bersama Pemko Batam terkait penataan pesisir, serta pertukaran mahasiswa dengan Universitas di Malaysia.\", \"mitra_dudi\": 34, \"mitra_pemerintah\": 12, \"mitra_internasional\": 6}','{\"it_digital\": \"Upgrade backbone fiber optic antar gedung menjadi 1 Gbps, implementasi server cloud cadangan, serta penerapan SIM Kinerja dan Sistem Presensi QR Dinamis.\", \"sarana_fisik\": \"Perluasan Gedung Rektorat dan Perkuliahan Terpadu, renovasi laboratorium CNC dan Robotika, serta penambahan fasilitas Creative Hub & Co-working Space mahasiswa.\"}','1. Kendala masa tunggu akreditasi instrumen baru LAM yang membutuhkan pemenuhan luaran publikasi secara cepat.\nSolusi: Diberikan reward insentif khusus bagi dosen yang berhasil publish artikel di jurnal Scopus Q1-Q3 dan SINTA 2.\n2. Tantangan persaingan penerimaan mahasiswa baru di era digital.\nSolusi: Mengoptimalkan digital marketing, program referral alumni, dan kerjasama beasiswa kemitraan industri.','1. Pembukaan prodi baru Magister Teknik Informatika (S2) dan Rekayasa Perangkat Lunak.\n2. Akselerasi peningkatan 8 dosen berkualifikasi lektor kepala menjadi Guru Besar (Profesor).\n3. Pembangunan Gedung Laboratorium Terpadu tahap II untuk menunjang riset berstandar internasional.',2,2,'2026-09-12 00:33:03','2026-09-12 00:33:03');
/*!40000 ALTER TABLE `laporan_pengembangans` ENABLE KEYS */;
UNLOCK TABLES;

